const config = $input.first().json;
if (typeof config.demo_mode !== 'boolean') throw new Error('demo_mode must be a boolean.');
if (!Number.isInteger(config.lookahead_days) || config.lookahead_days < 1 || config.lookahead_days > 30) throw new Error('lookahead_days must be an integer between 1 and 30.');
if (!Number.isInteger(config.max_report_pairs) || config.max_report_pairs < 1 || config.max_report_pairs > 100) throw new Error('max_report_pairs must be an integer between 1 and 100.');
new Intl.DateTimeFormat('en-GB', { timeZone: config.report_timezone });
if (!config.demo_mode) {
  if (typeof config.calendar_id !== 'string' || !config.calendar_id.trim()) throw new Error('Choose a calendar ID.');
  if (!/^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/.test(String(config.recipient_email || ''))) throw new Error('Choose one internal recipient email address.');
}
return [{ json: config }];

const base = $now.startOf('day').plus({ days: 1, hours: 10 });
const make = (id, title, startMinutes, endMinutes, extra = {}) => ({ json: {
  id, summary: title, status: 'confirmed',
  start: { dateTime: base.plus({ minutes: startMinutes }).toISO() },
  end: { dateTime: base.plus({ minutes: endMinutes }).toISO() }, ...extra,
} });
return [
  make('demo-a', 'Example appointment A', 0, 60),
  make('demo-b', 'Example appointment B', 30, 90),
  make('demo-c', 'Example appointment C', 90, 120),
  make('demo-cancelled', 'Example cancelled appointment', 15, 45, { status: 'cancelled' }),
  make('demo-free', 'Example free event', 15, 45, { transparency: 'transparent' }),
];

const config = $('Configure calendar and report').first().json;
const timeZone = String(config.report_timezone || 'Europe/Madrid');
const formatter = new Intl.DateTimeFormat('en-GB', {
  timeZone, dateStyle: 'medium', timeStyle: 'short',
});
const demoMode = config.demo_mode === true;
if (typeof config.demo_mode !== 'boolean') throw new Error('demo_mode must be a boolean.');
if (!demoMode && !/^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/.test(String(config.recipient_email || ''))) {
  throw new Error('Configure one recipient email address before turning demo mode off.');
}
const displayLimit = Number(config.max_report_pairs ?? 25);
if (!Number.isInteger(displayLimit) || displayLimit < 1 || displayLimit > 100) {
  throw new Error('max_report_pairs must be an integer between 1 and 100.');
}
const items = $input.all();
const events = [];
const seen = new Set();
const invalid = [];
const skipped = { cancelled: 0, transparent: 0, declined: 0, allDay: 0, duplicate: 0 };
const label = value => String(value || 'Untitled appointment').replace(/[\r\n\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, 180);
const parseInstant = value => {
  if (typeof value !== 'string' || !/(?:Z|[+-]\d{2}:\d{2})$/i.test(value)) return NaN;
  return Date.parse(value);
};
for (const { json: event } of items) {
  if (!event || Object.keys(event).length === 0) continue;
  if (event.status === 'cancelled') { skipped.cancelled++; continue; }
  if (event.transparency === 'transparent') { skipped.transparent++; continue; }
  if (event.attendees?.some(attendee => attendee.self === true && attendee.responseStatus === 'declined')) {
    skipped.declined++; continue;
  }
  if (event.start?.date && !event.start.dateTime) { skipped.allDay++; continue; }
  const start = parseInstant(event.start?.dateTime);
  const end = parseInstant(event.end?.dateTime);
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
    invalid.push(label(event.summary)); continue;
  }
  const key = `${event.id || ''}|${start}|${end}`;
  if (event.id && seen.has(key)) { skipped.duplicate++; continue; }
  if (event.id) seen.add(key);
  events.push({ title: label(event.summary), start, end });
}
events.sort((left, right) => left.start - right.start || left.end - right.end);
let conflictCount = 0;
const pairs = [];
let active = [];
for (const event of events) {
  active = active.filter(previous => previous.end > event.start);
  for (const previous of active) {
    conflictCount++;
    if (pairs.length < displayLimit) pairs.push({
      first: previous.title,
      second: event.title,
      overlapStart: new Date(Math.max(previous.start, event.start)).toISOString(),
      overlapEnd: new Date(Math.min(previous.end, event.end)).toISOString(),
    });
  }
  active.push(event);
}
const lines = [
  `Calendar audit: ${conflictCount} overlapping appointment pair(s).`,
  `Checked ${events.length} timed appointment(s). Times shown in ${timeZone}.`,
  '',
];
for (let index = 0; index < pairs.length; index++) {
  const pair = pairs[index];
  lines.push(`${index + 1}. ${pair.first} / ${pair.second}`,
    `   ${formatter.format(new Date(pair.overlapStart))} to ${formatter.format(new Date(pair.overlapEnd))}`);
}
if (conflictCount > pairs.length) lines.push('', `Showing ${pairs.length} of ${conflictCount} pairs. Increase max_report_pairs to see more.`);
if (invalid.length) lines.push('', `${invalid.length} event(s) could not be checked because their timed dates were invalid or missing a UTC offset.`,
  ...invalid.slice(0, 10).map(title => `- ${title}`));
const ignoredCount = Object.values(skipped).reduce((sum, count) => sum + count, 0);
if (ignoredCount) lines.push('', `Excluded: ${skipped.cancelled} cancelled, ${skipped.transparent} free, ${skipped.declined} declined, ${skipped.allDay} all-day, ${skipped.duplicate} duplicate event(s).`);
if (!conflictCount && !invalid.length) lines.push('No timed appointment overlaps found in the retrieved events.');
lines.push('', 'Review the affected appointments in Google Calendar. This workflow leaves the calendar unchanged.');
return [{ json: {
  demoMode, checkedEvents: events.length, conflictCount, pairs, invalidEvents: invalid.length, skipped,
  needsAttention: conflictCount > 0 || invalid.length > 0,
  subject: `Calendar audit: ${conflictCount} overlap(s)${invalid.length ? `, ${invalid.length} unchecked event(s)` : ''}`,
  reportText: lines.join('\n'), recipientEmail: String(config.recipient_email || ''),
} }];
